    expect(read('test/parser.test.ts')).not.toContain("describe('post186 ci-config HEAVY deepen");
    expect(read('test/routes.test.ts')).not.toContain("describe('post186 ci-config HEAVY deepen");
    expect(read('test/genres.test.ts')).not.toContain("describe('post186 ci-config HEAVY deepen");
