  it('post204-ultra: .github/workflows/ci.yml line[2] sha256', () => { expect(createHash('sha256').update(read('.github/workflows/ci.yml').split('\n')[2], 'utf8').digest('hex')).toBe('fc8135fd1264162a0a9b1fb413cf3ab58a2f07a0d78717ded78108a950ea7b75') });
