  it('post215-ultra: CI concurrency group uses workflow+ref', () => {
    expect(read('.github/workflows/ci.yml')).toContain('group: ci-${{ github.workflow }}-${{ github.ref }}');
  });
  it('post215-ultra: CI defaults shell bash', () => {
    expect(read('.github/workflows/ci.yml')).toMatch(/shell:\s*bash/);
  });
  it('post215-ultra: hygiene asserts coverage thresholds greps', () => {
    const ci = read('.github/workflows/ci.yml');
    expect(ci).toContain("grep -q 'branches: 100'");
    expect(ci).toContain("grep -q 'lines: 100'");
    expect(ci).toContain("grep -q 'functions: 100'");
    expect(ci).toContain("grep -q 'statements: 100'");
  });
  it('post215-ultra: deploy still requires GEMINI_API_KEY secret reference', () => {
    expect(read('.github/workflows/deploy.yml')).toContain('GEMINI_API_KEY');
    expect(read('.github/workflows/deploy.yml')).toContain('secrets.GEMINI_API_KEY');
  });
  it('post215-ultra: wrangler.toml forbids inline GEMINI_API_KEY assignment', () => {
    expect(read('wrangler.toml')).not.toMatch(/GEMINI_API_KEY\s*=/);
  });
