  it('post220-extras: sha256 package.json', () => { expect(sha256("package.json")).toBe("34552493f3008b58991d10e7b41ee0ecaa43bf8ba3e79d261ac2a061e6f7181c"); });
  it('post220-extras: sha256 package-lock.json', () => { expect(sha256("package-lock.json")).toBe("5f8a888f1fc7aaf97dcdaa3f91405cefbb45ad118685eac7a1488b78cedfcee6"); });
  it('post220-extras: sha256 vitest.config.ts', () => { expect(sha256("vitest.config.ts")).toBe("f9b58bb937531da55ad474592e69ec95c6d55a5b8b878f8fa251c0f8d6caff38"); });
  it('post220-extras: sha256 tsconfig.json', () => { expect(sha256("tsconfig.json")).toBe("ef73d52e26c5dbe1f1785a067cbc04688ea1e6ef80ca5fff4a7351583828d792"); });
  it('post220-extras: sha256 wrangler.toml', () => { expect(sha256("wrangler.toml")).toBe("95b11779a88f0544f3561eea67994a0b0b874d7b8776579189fa7142fa0473f8"); });
  it('post220-extras: sha256 AGENTS.md', () => { expect(sha256("AGENTS.md")).toBe("48e590b4f146e2fbd1ebb409e0d5a5ec1be50b72b2c310f1c1e360487b36feaa"); });
  it('post220-extras: sha256 DEPLOY.md', () => { expect(sha256("DEPLOY.md")).toBe("11067fa2da7ee6d2354842e1c258f363d487536ac307b76739893a93b0c9d05a"); });
  it('post220-extras: sha256 README.md', () => { expect(sha256("README.md")).toBe("f7ecd30301c01e7af03a64ca32d1368a10cac861c09016c718e39417dc15c987"); });
  it('post220-extras: sha256 .cursor/environment.json', () => { expect(sha256(".cursor/environment.json")).toBe("4ed3537a1a4141c61be528b8ca3bd121164ab2bed7d0a9b95c34ce81cca99694"); });
  it('post220-extras: sha256 .gitignore', () => { expect(sha256(".gitignore")).toBe("474ed59338a23de819e219c00d0e033b23e3669cc4106ce7a888fe0636569698"); });
